-- Satu buku (Budi). id, lawan, dan jumlah dari rekaman pagination.txt bagian A; jam dibuat ditulis ulang sederhana (Ilustrasi).
CREATE TABLE posting (id INTEGER PRIMARY KEY, lawan TEXT NOT NULL, jumlah INTEGER NOT NULL, dibuat TEXT NOT NULL);
CREATE INDEX posting_riwayat ON posting (dibuat, id);
